export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity, m = inputs.mass;
  const T = 2 * u / g, ta = u / g;
  const t = sdk.clamp(time, 0, T);
  const h = Math.max(0, u * t - g * t * t / 2);
  const v = u - g * t;
  const F = m * g;
  const apexH = u * u / (2 * g);
  let st = 'Falling';
  if (t <= 0) st = 'Ready to toss';
  else if (Math.abs(t - ta) < 0.005) st = 'At the top';
  else if (t < ta) st = 'Rising';
  else if (t >= T - 1e-6) st = 'Back at launch height';
  const by = 370 - h * 280 / 2.2;
  const bx = 110;
  const o = [];
  o.push(...sdk.panel({ id: 'lane.motion', x: 10, y: 40, w: 300, h: 370, title: 'The motion', state: st }));
  o.push(...sdk.panel({ id: 'lane.graph', x: 330, y: 40, w: 300, h: 370, title: 'Velocity over time', state: 'a = -g' }));
  o.push(sdk.axis('axis.height', { x: 60, y: 370, length: 280, orientation: 'y', min: 0, max: 2.2, ticks: [0, 0.5, 1, 1.5, 2], label: 'Height', unit: 'm' }));
  o.push(sdk.circle('ball.toss', bx, by, 28, { role: 'output' }));
  o.push(...sdk.vector('vec.v', { x: bx + 30, y: by }, { value: v, direction: 'up' }, { scale: 12, label: 'v', role: 'input' }));
  o.push(...sdk.vector('vec.a', { x: bx + 58, y: by }, { value: -g, direction: 'up' }, { scale: 5, label: 'a', role: 'warning' }));
  o.push(...sdk.callout(bx + 90, Math.max(by - 30, 90), ['v = ' + sdk.format(v, 2) + ' m/s', 'a = ' + sdk.format(-g, 1) + ' m/s²', 'Fg = ' + sdk.format(F, 1) + ' N'], { id: 'callout.toss' }));
  const n = 12;
  const tr = [];
  for (let i = 0; i <= n; i++) { const s = t * i / n; tr.push({ x: s, y: u - g * s }); }
  if (t <= 0) tr.push({ x: 0.0001, y: u - g * 0.0001 });
  const co = [];
  for (let i = 0; i <= n; i++) { const s = t + (T - t) * i / n; co.push({ x: s, y: u - g * s }); }
  const a0 = Math.max(0, t - 0.2), a1 = Math.min(T, t + 0.2);
  const sl = [{ x: a0, y: v + (-g) * (a0 - t) }, { x: a1, y: v + (-g) * (a1 - t) }];
  o.push(sdk.plot('plot.vt', { x: 395, y: 70, w: 225, h: 260, axes: { x: { label: 'Time', min: 0, max: 1.8, unit: 's' }, y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' } }, series: [{ label: 'v up to now', kind: 'line', points: tr }, { label: 'continuation', kind: 'line', points: co }, { label: 'slope a = -g', kind: 'line', points: sl }] }));
  o.push(sdk.text('plot.vt.note', 480, 395, 'slope a = -g = ' + sdk.format(-g, 1) + ' m/s²', { align: 'middle' }));
  return {
    frame: { width: 640, height: 420, objects: o, readouts: [{ id: 'velocity', value: v }, { id: 'acceleration', value: -g }, { id: 'force', value: F }, { id: 'motionState', value: st }] },
    quantities: { launchSpeed: u, gravity: g, mass: m, apexTime: ta, apexHeight: apexH, height: h, velocity: v, acceleration: -g, force: F }
  };
}
